D.guides.warlock = {
 {
  id="wl-destro-mobalytics60",
  spec="Destruction",
  label="Destruction · Mobalytics level 60 14/4/33 (order derived)",
  kind="final-derived",
  default=true,
  note="The level-60 allocation is exact (Mobalytics, Crix, 2026-10-23). The guide gives no levelling order, so the Companion derived one: Destruction rows first (Bane, Aftermath, Ruin, Shadowburn, Conflagrate...), then Affliction, then Demonology.",
  priorities="Endgame raid build, read from the embedded 51/51 talent display. Succubus as the active pet. Keep Conflagrate and Shadowburn on cooldown for a permanent Shadow and Flame buff (Shadowburn shard is refunded at 5/5). Incinerate is the main filler. Bane of Doom on long fights, otherwise Bane of Agony. Curse of the Elements by default. Ruin and Agonizing Flames for crit and damage, Bane of Havoc for cleave. For leveling, the guide points to its separate Warlock Leveling Guide, which only covers Affliction and Demonology.",
  source={
   site="Mobalytics",
   author="Crix",
   title="Destruction Warlock Guide - Talents, Rotations, Races & More",
   url="https://mobalytics.gg/wow-forever/classes/destruction-warlock-guide",
   updated="2026-10-23",
   scope="60",
   purpose="raid"
  },
  order={"bane","bane","bane","bane","bane","cataclysm","cataclysm","cataclysm","aftermath","aftermath","aftermath","aftermath","aftermath","ruin","ruin","ruin","ruin","ruin","shadowburn","agonizing-flames","agonizing-flames","agonizing-flames","conflagrate","bane-of-havoc","fire-and-brimstone","fire-and-brimstone","fire-and-brimstone","shadow-and-flame","shadow-and-flame","shadow-and-flame","shadow-and-flame","shadow-and-flame","incinerate","improved-life-tap","improved-life-tap","suppression","suppression","suppression","suppression","suppression","improved-corruption","improved-corruption","improved-corruption","amplify-curse","pandemic","pandemic","pandemic","unholy-power","unholy-power","unholy-power","unholy-power"}
 },
 {
  id="wl-destro-tavern30",
  spec="Destruction",
  label="Destruction · Warcraft Tavern level 30 5/0/20 (order derived)",
  kind="final-derived",
  default=false,
  note="Allocation is exact (Zephan). The guide lists the talents in an order that is not legal as written (row 4 before 15 points), so the Companion derived a legal order. The 26th point is flex (Bane of Havoc or Improved Life Tap).",
  priorities="Core 15 points: Bane 5 (-0.5s on Shadow Bolt/Immolate), Aftermath 5, Shadowburn 1, Conflagrate 1, Agonizing Flames 3. Then Cataclysm 3 for mana, and 2 points in Destructive Reach (preferred, range) or Ruin (weak until you have more crit) to reach 20 in Destruction. Then Suppression 5 for hit and lower threat. The 26th point is flex: Bane of Havoc for big dungeon packs, or Improved Life Tap. Solo variant from the guide: Suppression 3 + Improved Life Tap 2 + Improved Corruption 1 in place of Suppression 5 + flex. Without Legacy points (21 points at level 30), the guide does not say which 5 to drop. The guide links a generic calculator (https://www.warcrafttavern.com/forever/tools/talent-calculator/warlock) and gives no build-specific link.",
  source={
   site="Warcraft Tavern",
   author="Zephan",
   title="Destruction Warlock Guide - WoW Forever (Level 30 Beta Build)",
   url="https://www.warcrafttavern.com/forever/guides/destruction-warlock/",
   scope="10–30 (25 of 26 points; 1 flex)",
   purpose="leveling/dungeon"
  },
  order={"bane","bane","bane","bane","bane","destructive-reach","destructive-reach","aftermath","aftermath","aftermath","aftermath","aftermath","cataclysm","cataclysm","cataclysm","shadowburn","conflagrate","agonizing-flames","agonizing-flames","agonizing-flames","suppression","suppression","suppression","suppression","suppression"}
 },
 {
  id="wl-destro-wowhead30",
  spec="Destruction",
  label="Destruction · Wowhead level 30 priorities",
  kind="priorities",
  default=false,
  note="Priorities only: \"take these first\" Bane 5, Aftermath 5, Shadowburn, Conflagrate, Agonizing Flames 3; the rest is playstyle.",
  priorities="'Take these first': Bane 5/5, Aftermath 5/5, Shadowburn 1/1 (called 'the most valuable point in the build'), Conflagrate 1/1, Agonizing Flames 3/3. 'The rest is playstyle', no ranks given: Cataclysm, Improved Life Tap, Improved Corruption (1/5 brings Corruption close to the GCD), Suppression (more hits, less threat, helps the Voidwalker hold aggro), Ruin (mostly a filler point until you have crit), Molten Skin, Destructive Reach, Improved Shadow Bolt (needs more crit to matter), Demonic Embrace. With Legacy points (20 in Destruction): Bane of Havoc (good for cleave), and optionally Fire and Brimstone. Playstyle: Voidwalker tanks, DoT up (Bane of Agony, Corruption, Immolate), then wand or Shadow Bolt filler, Conflagrate just before Immolate expires, Shadowburn as the killing blow to get the shard back.",
  source={
   site="Wowhead",
   author="Zephan",
   title="Level 30 Destruction Warlock Guide: Talents, Rotation and Gearing - Forever",
   url="https://www.wowhead.com/forever/guide/classes/warlock/destruction/level-30-dps-overview",
   updated="2026-10-09",
   scope="10-30 (beta cap)",
   purpose="leveling/dungeon"
  },
  order={}
 },
 {
  id="wl-aff-mobalytics-level",
  spec="Affliction",
  label="Affliction · Mobalytics Drain Tank levelling 36/12/0 (10–57)",
  kind="exact-order",
  default=false,
  note="Exact level table from the guide (Crix, 2026-10-26). Points 49–51 are flex in the guide and are left open here.",
  priorities="Drain Tank style: DoT up, send the demon in, then Drain Life to face-tank while the DoTs finish the mob. The level table gives one talent per level range: 10-14 Improved Corruption 5 (instant Corruption), 15-17 Suppression 3, 18-19 Grim Reach 2, 20-21 Soul Harvest 2, 22-24 Improved Drains 3, 25-26 Nightfall 2, 27-29 Fel Concentration 3 (70% pushback protection, 'VITAL'), 30-32 Soul Siphon 3, 33-34 Pandemic 2, 35-39 Shadow Mastery 5, 40 Pandemic 3/3, 41-45 Unholy Power 5, 46-47 Demonic Energies 2, 48-52 Malevolence 5, 53-55 Fel Vitality 3, 56-57 Master Summoner 2, 58-60 flex. Flex options: Curse of Exhaustion (PvP servers), Siphon Life + Wrack, Improved Bane of Agony, Improved Life Tap, or more Suppression. With the Legacy 'Talented' perk, follow the same order starting at level 5.",
  source={
   site="Mobalytics",
   author="Crix",
   title="Warlock Leveling Guide (Level 1-60) - Affliction 1-60 Leveling (Drain Tank)",
   url="https://mobalytics.gg/wow-forever/classes/warlock-leveling-guide",
   updated="2026-10-26",
   scope="10–57 (+3 flex points at 58–60)",
   purpose="leveling"
  },
  order={"improved-corruption","improved-corruption","improved-corruption","improved-corruption","improved-corruption","suppression","suppression","suppression","grim-reach","grim-reach","soul-harvest","soul-harvest","improved-drains","improved-drains","improved-drains","nightfall","nightfall","fel-concentration","fel-concentration","fel-concentration","soul-siphon","soul-siphon","soul-siphon","pandemic","pandemic","shadow-mastery","shadow-mastery","shadow-mastery","shadow-mastery","shadow-mastery","pandemic","unholy-power","unholy-power","unholy-power","unholy-power","unholy-power","demonic-energies","demonic-energies","malevolence","malevolence","malevolence","malevolence","malevolence","fel-vitality","fel-vitality","fel-vitality","master-summoner","master-summoner"}
 },
 {
  id="wl-aff-mobalytics60",
  spec="Affliction",
  label="Affliction · Mobalytics level 60 30/0/21 (order derived)",
  kind="final-derived",
  default=false,
  note="Level-60 allocation is exact; the levelling order is derived by the Companion (Affliction first, then Destruction).",
  priorities="Endgame build read from the embedded 51/51 talent display. Bane of Agony, Corruption and Immolate kept at full uptime. Shadow Bolt or wand as filler, and instant Shadow Bolt on Nightfall procs. Curse of the Elements or Recklessness on elites and bosses. Life Tap below about 40% mana. Succubus as the damage pet, Voidwalker for safety. 21 Destruction points (Improved Shadow Bolt 5, Bane 5, Ruin 5) favor Shadow Bolt as filler.",
  source={
   site="Mobalytics",
   author="Crix",
   title="Affliction Warlock Guide - Talents, Rotations, Races & More",
   url="https://mobalytics.gg/wow-forever/classes/affliction-warlock-guide",
   updated="2026-10-23",
   scope="60",
